from django.shortcuts import render
from rest_framework import generics, status
from rest_framework.views import APIView
from rest_framework.response import Response
from .models import Attendance, PermissionRequest
from .serializers import (
    AttendanceSerializer,
    RFIDCheckInSerializer,
    FinalizeSessionQRSerializer,
    PermissionRequestCreateSerializer,
    CloseSessionSerializer,
)

class AttendanceListCreateView(generics.ListCreateAPIView):
    queryset = Attendance.objects.all()
    serializer_class = AttendanceSerializer

class AttendanceDetailView(generics.RetrieveUpdateDestroyAPIView):
    queryset = Attendance.objects.all()
    serializer_class = AttendanceSerializer

class RFIDCheckInView(APIView):
    def post(self, request):
        serializer = RFIDCheckInSerializer(data=request.data)
        if serializer.is_valid():
            # Implement check-in logic here
            return Response(serializer.validated_data, status=status.HTTP_200_OK)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class FinalizeSessionQRView(APIView):
    def post(self, request):
        serializer = FinalizeSessionQRSerializer(data=request.data)
        if serializer.is_valid():
            att = serializer.create(serializer.validated_data)
            return Response(AttendanceSerializer(att).data, status=status.HTTP_200_OK)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

class PermissionRequestCreateView(generics.CreateAPIView):
    queryset = PermissionRequest.objects.all()
    serializer_class = PermissionRequestCreateSerializer

class CloseSessionView(APIView):
    def post(self, request):
        serializer = CloseSessionSerializer(data=request.data)
        if serializer.is_valid():
            # Implement close session logic here
            return Response(serializer.validated_data, status=status.HTTP_200_OK)
        return Response(serializer.errors, status=status.HTTP_400_BAD_REQUEST)

from django.urls import path, include from rest_framework.routers import DefaultRouter from .views import ( CourseViewSet, ClassSessionViewSet, TimeTableListCreateView, CreateAdhocSessionView, SessionQRActivateView, SessionQRDeactivateView, SessionCancelView, )
router = DefaultRouter() router.register(r'courses', CourseViewSet) router.register(r'class-sessions', ClassSessionViewSet)
urlpatterns = [ path('', include(router.urls)), path('timetable/', TimeTableListCreateView.as_view(), name='timetable-list-create'), path('session/adhoc/', CreateAdhocSessionView.as_view(), name='create-adhoc-session'), path('session/qr-activate/', SessionQRActivateView.as_view(), name='session-qr-activate'), path('session/qr-deactivate/', SessionQRDeactivateView.as_view(), name='session-qr-deactivate'), path('session/cancel/', SessionCancelView.as_view(), name='session-cancel'), ]
